excels.excel:

EXPORT WITH SHEET="采购价格对比分析", HEADER=true,
    MAPPING={"a":"物料名称","b":"供应商","c":"基准价","d":"报价","e":"价差","f":"价差率","g":"价格评定"},
    FORMAT={"c":"#,##0.00","d":"#,##0.00","e":"#,##0.00","f":"0.00%"},
    FORMULAS={
        E2:'D2-C2',F2:'E2/C2',
        E3:'D3-C3',F3:'E3/C3',
        E4:'D4-C4',F4:'E4/C4',
        E5:'D5-C5',F5:'E5/C5',
        E6:'D6-C6',F6:'E6/C6',
        C7:'AVERAGE(C2:C6)',D7:'AVERAGE(D2:D6)',E7:'D7-C7',F7:'E7/C7'
    },
    STYLE={
        ROW 7:{bold:true,fillPattern:solid_foreground,fillForegroundColor:lightYellow,alignment:right,verticalAlignment:center},
        F4:{color:red,bold:true}
    }
